mapper.insert:
INSERT INTO TBL_PERIOD_END_CHECK (
    CHECK_ID, CHECK_ITEM_ID, ACCOUNTING_PERIOD, BOOK_ID, TENANT_ID,
    CHECK_RESULT, ERROR_MESSAGE, CHECK_TIME, STATUS,
    CREATE_TIME, CREATOR
) VALUES (
    #{checkId}, #{checkItemId}, #{accountingPeriod}, #{bookId}, #{tenantId},
    #{checkResult}, #{errorMessage}, #{checkTime}, #{status},
    SYSDATE, #{creator}
)

mapper.select:
SELECT CLOSING_ID as closingId, ACCOUNTING_PERIOD as accountingPeriod, CLOSING_TYPE as closingType, CLOSING_STATUS as closingStatus, CLOSING_TIME as closingTime, CLOSING_USER as closingUserId, (SELECT USERNAME FROM TBL_USER WHERE USER_ID = CLOSING_USER) as closingUserName, CLOSING_DESCRIPTION as closingDescription, VOUCHER_COUNT as voucherCount, TOTAL_AMOUNT as totalAmount, DURATION as duration, REVERSE_REASON as reverseReason, REVERSE_TIME as reverseTime, REVERSE_USER as reverseUserId, (SELECT USERNAME FROM TBL_USER WHERE USER_ID = REVERSE_USER) as reverseUserName, BOOK_ID as bookId FROM TBL_PERIOD_END_CLOSING WHERE BOOK_ID = #{bookId}
AND ACCOUNTING_PERIOD = #{accountingPeriod}
ORDER BY CLOSING_TIME DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_PERIOD_END_CLOSING
WHERE BOOK_ID = #{bookId}

    AND ACCOUNTING_PERIOD = #{accountingPeriod}
